// 🖼️ Photo-style mockup scenes. The free image AI paints each room or desk once
// (an empty wall, a tidy desk…) and the app places your design into it: in a real-
// looking frame, or on a laptop, tablet or printed page. Backgrounds are reused
// across products (a small library in your storage), so most products cost no
// extra AI at all. Every picture is generated by you, so it counts as your own
// image for Etsy (no stock photos).
import type { ProductFormat } from "./format";

export type SceneKind = "frame" | "gallery" | "laptop" | "tablet" | "paper";

export interface SceneDef {
  id: string;
  label: string;
  kind: SceneKind;
  /** Frame colour for frame scenes. */
  frame?: "oak" | "white" | "black";
  prompt: string;
}

const NOTHING_ON_WALL = "Nothing hanging on the wall: no pictures, no frames, no posters, no art, no text, no shelves on the wall.";
const PHOTO = "Realistic interior photograph, soft natural daylight, warm cosy tones, high detail, sharp focus.";

export const SCENES: Record<string, SceneDef> = {
  living: {
    id: "living",
    label: "Living room",
    kind: "frame",
    frame: "oak",
    prompt: `Front view, straight-on, of a cosy Scandinavian living room. A large plain empty warm-white wall fills the upper two thirds of the picture; a soft beige sofa with cushions and a knitted throw sits low along the bottom. A leafy plant at one side. ${PHOTO} ${NOTHING_ON_WALL}`,
  },
  nursery: {
    id: "nursery",
    label: "Nursery",
    kind: "frame",
    frame: "white",
    prompt: `Front view, straight-on, of a calm pastel nursery. A large plain empty pale cream wall fills the upper two thirds of the picture; a white wooden dresser with a small soft toy and a basket sits low along the bottom. ${PHOTO} ${NOTHING_ON_WALL}`,
  },
  bedroom: {
    id: "bedroom",
    label: "Bedroom",
    kind: "frame",
    frame: "black",
    prompt: `Front view, straight-on, of a calm modern bedroom. A large plain empty soft greige wall fills the upper two thirds of the picture; the top of a linen bed headboard with pillows sits low along the bottom, a small bedside lamp at one side. ${PHOTO} ${NOTHING_ON_WALL}`,
  },
  hallway: {
    id: "hallway",
    label: "Gallery wall",
    kind: "gallery",
    frame: "black",
    prompt: `Front view, straight-on, of a bright hallway. A wide plain empty white wall fills the upper two thirds of the picture; a low oak console table with a vase of dried flowers and a ceramic bowl sits along the bottom. ${PHOTO} ${NOTHING_ON_WALL}`,
  },
  desk: {
    id: "desk",
    label: "Laptop",
    kind: "laptop",
    prompt: `Front view of a tidy light wooden desk against a soft plain wall, a coffee mug, a small plant and a notebook at the sides, a wide empty clear space in the middle of the desk. ${PHOTO} No laptop, no computer, no screens, no text.`,
  },
  flatlay: {
    id: "flatlay",
    label: "Tablet",
    kind: "tablet",
    prompt: `Top-down flat lay photograph of a cosy cream knitted blanket with a mug of tea, a few autumn leaves and a pen at the edges, a large empty space in the middle. Soft natural daylight, warm tones, high detail. No tablet, no phone, no screens, no paper, no text.`,
  },
  table: {
    id: "table",
    label: "Printed",
    kind: "paper",
    prompt: `Top-down photograph of a light oak table with a pencil, a cup of coffee, a sprig of eucalyptus and a pair of glasses at the edges, a large empty space in the middle. Soft natural daylight, warm tones, high detail. No paper, no documents, no text.`,
  },
};

/** The scenes a product is shown in, by format. */
export function scenesFor(format: ProductFormat): SceneDef[] {
  const ids = format === "art" ? ["living", "nursery", "bedroom", "hallway"] : format === "excel" ? ["desk", "flatlay", "table"] : ["table", "flatlay", "desk"];
  return ids.map((id) => SCENES[id]);
}

/** How many different backgrounds to keep per scene before reusing them. */
export const SCENE_VARIANTS = 2;
export const sceneKey = (scene: string, n: number) => `products/_scenes/${scene}-${n + 1}-${Date.now().toString(36)}.b64`;

/** A mockup ready to draw: the scene, its background photo (if painted), and what goes in it. */
export interface MockupView {
  scene: string;
  seed: number;
  /** AI-painted background (null = plain styled backdrop). */
  bgKey?: string | null;
  /** The art, or the spreadsheet / printable picture to show. */
  imageKey?: string | null;
  slogan?: string | null;
}
